import React, { useState, useEffect } from "react";
import EarthScene from "./EarthScene";
import axios from "axios";

const Home = () => {
  const [startSpace, setStartSpace] = useState(false);
  const [debrisData, setDebrisData] = useState([]);

  useEffect(() => {
    axios.get("http://localhost:5000/api/debris")
      .then(res => setDebrisData(res.data))
      .catch(err => console.error(err));
  }, []);

  if (startSpace) return <EarthScene />;

  return (
    <div style={{ padding: "30px", fontFamily: "Arial, sans-serif", backgroundColor: "#000022", color: "#fff", minHeight: "100vh",justifyContent: "center",alignItems: "center",
        alignItems: "center",}}>
      <h1>Welcome to Space Debris Tracker</h1>
      <p>Click the button below to enter the space visualization.</p>
      <button
        onClick={() => setStartSpace(true)}
        style={{ padding: "15px 30px", 
        fontSize: "18px", 
        cursor: "pointer", 
        backgroundColor: "#0044ff",
        color: "#fff",
        border: "none",
        borderRadius: "10px", 
        justifyContent: "center",
        alignItems: "center",
        
        marginTop: "20px" }}
      >
        Enter Space
      </button>

      <h2 style={{ marginTop: "40px",textAlign: "center" }}>Live Satellite Telemetry Feed</h2>
      <table style={{ width: "100%", marginTop: "10px", borderCollapse: "collapse" }}>
        <thead>
          <tr>
            <th style={{ border: "1px solid #fff", padding: "8px" }}>Name</th>
            <th style={{ border: "1px solid #fff", padding: "8px" }}>Latitude</th>
            <th style={{ border: "1px solid #fff", padding: "8px" }}>Longitude</th>
            <th style={{ border: "1px solid #fff", padding: "8px" }}>Altitude (km)</th>
          </tr>
        </thead>
        <tbody>
          {debrisData.map((d, i) => (
            <tr key={i}>
              <td style={{ border: "1px solid #fff", padding: "8px" }}>{d.name}</td>
              <td style={{ border: "1px solid #fff", padding: "8px" }}>{d.lat.toFixed(2)}</td>
              <td style={{ border: "1px solid #fff", padding: "8px" }}>{d.lon.toFixed(2)}</td>
              <td style={{ border: "1px solid #fff", padding: "8px" }}>{d.alt.toFixed(2)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default Home;
